// WantsBlink reports whether an Images row or a registry-browser tag row is in
// an animated state (running, or an action observed on it), or whether the
// footer shows a load of the view's own. A queued row and a remembered failure
// are steady. It is the level the router's BlinkingView
// check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	if m.registryBrowser != nil && m.registryBrowser.WantsBlink() {
		return true
	}
	// A busy row (network, volume, registry) and a group being discovered both
	// show a blinking dot.
	return m.footerLoading() ||
		len(m.refreshingGroups) > 0 ||
		len(m.networkTable.BusyLabels()) > 0 ||
		len(m.volumeTable.BusyLabels()) > 0 ||
		len(m.registryTable.BusyLabels()) > 0
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
// how the two drift.
func (b *RegistryBrowser) SetJobs(runs []jobs.Run, failures []jobs.Failure, context string) {
	b.jobs = runs
	b.failures = slices.Clone(failures)
	b.contextName = context
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetBlinkPhase hands the router's blink phase to the tag table. Nothing is
// rebuilt: the table reads the phase at render.
func (b *RegistryBrowser) SetBlinkPhase(on bool) { b.tagTable.SetBlinkPhase(on) }

// WantsBlink reports whether a visible tag row has a running operation.
func (b *RegistryBrowser) WantsBlink() bool {
	if b.state != browserStateTags {
		return false
	}
	for _, r := range b.tagTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	return false
}

