	}
	m = imagesModel(t)
	if m.WantsBlink() {
		t.Error("WantsBlink is true at rest on level 1")
	}
}

func TestLevelOneTakesTheBlinkPhase(t *testing.T) {
	m := imagesModel(t)
	m = feed(t, m, jobs.FrameMsg{Blink: false})
