		t.Error("the level 1 table did not take the off phase")
	}
	m = feed(t, m, jobs.FrameMsg{Blink: true})
	if !m.registryBrowser.searchTable.BlinkPhase() {
		t.Error("the level 1 table did not take the on phase")
	}
}

